package org.eclipse.rdf4j.common.iteration;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

@Execution(ExecutionMode.SAME_THREAD)
@Timeout(value = 20, unit = TimeUnit.SECONDS)
class TimeLimitIterationSchedulerOwnershipTest {

	@Test
	void pendingAutomaticCleanupRetainsOnlyItsOwnRealSchedulerLease() throws Exception {
		LinkedBlockingQueue<Runnable> dispatch = new LinkedBlockingQueue<>();
		AtomicReference<TimeLimitIteration<String>> owner = new AtomicReference<>();
		AtomicInteger closes = new AtomicInteger();
		IllegalStateException bodyFailure = new IllegalStateException("source failed during timeout");
		CloseableIteration<String> source = new CloseableIteration<>() {
			@Override
			public boolean hasNext() {
				return true;
			}

			@Override
			public String next() {
				owner.get().interrupt();
				throw bodyFailure;
			}

			@Override
			public void remove() {
				throw new UnsupportedOperationException();
			}

			@Override
			public void close() {
				closes.incrementAndGet();
			}
		};
		long longBudget = TimeUnit.DAYS.toMillis(1);
		TimeLimitIteration<String> anchor = limited(new EmptyIteration<>(), longBudget, Runnable::run);
		TimeLimitIteration<String> pending = limited(source, longBudget, dispatch::add);
		owner.set(pending);
		Thread scheduler = null;
		try {
			scheduler = currentSchedulerThread();
			TimedOut timeout = assertThrows(TimedOut.class, pending::next);
			assertEquals(1, timeout.getSuppressed().length);
			assertSame(bodyFailure, timeout.getSuppressed()[0]);
			assertEquals(0, closes.get(), "queued cancellation has not closed its source");

			Runnable cancellation = dispatch.poll(5, TimeUnit.SECONDS);
			assertNotNull(cancellation, "the active-call timeout queued cooperative cancellation");
			cancellation.run();
			assertTrue(dispatch.isEmpty(), "unobserved active-call cleanup proceeds through escalation");
			assertEquals(0, closes.get(), "the explicit long grace keeps automatic cleanup pending");

			anchor.close();
			assertSame(scheduler, currentSchedulerThread(),
					"pending escalation owns the same real generation after the unrelated owner closes");
			pending.close();
			assertEquals(1, closes.get());
			scheduler.join(TimeUnit.SECONDS.toMillis(1));
			assertFalse(scheduler.isAlive(), "settling the actual last owner retires its exact scheduler thread");
		} finally {
			pending.close();
			Runnable action;
			while ((action = dispatch.poll()) != null) {
				action.run();
			}
			anchor.close();
		}
		assertEquals(1, closes.get(), "later explicit cleanup remains idempotent");
	}

	private static TimeLimitIteration<String> limited(CloseableIteration<String> source, long longBudget,
			TimeLimitIteration.AsyncLauncher launcher) {
		return new TimeLimitIteration<>(source, longBudget, longBudget, longBudget, launcher) {
			@Override
			protected void throwInterruptedException() {
				throw new TimedOut();
			}
		};
	}

	private static Thread currentSchedulerThread() throws InterruptedException {
		AtomicReference<Thread> thread = new AtomicReference<>();
		CountDownLatch captured = new CountDownLatch(1);
		TimeLimitScheduler.Task capture = new TimeLimitScheduler.Task(() -> {
		}, null, action -> {
			// dispatch.accept is called by wake on the actual shared scheduler, before any virtual-thread dispatch.
			thread.set(Thread.currentThread());
			try {
				action.run();
			} finally {
				captured.countDown();
			}
		});
		try {
			capture.schedule(new TimeLimitScheduler.Deadline(0, System.nanoTime()));
			assertTrue(captured.await(5, TimeUnit.SECONDS), "the real scheduler executes the identity probe");
			assertNotNull(thread.get());
			assertEquals("TimeLimitIteration scheduler", thread.get().getName());
			return thread.get();
		} finally {
			capture.cancel();
		}
	}

	private static final class TimedOut extends RuntimeException {
		private static final long serialVersionUID = 1L;
	}
}
